CREATE TABLE package_transactions(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,package_id TEXT NOT NULL,student_id TEXT NOT NULL,delta REAL NOT NULL,type TEXT NOT NULL,date TEXT NOT NULL,participant_id TEXT,reference_id TEXT,note TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,package_id) REFERENCES packages(tenant_id,id),FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id),FOREIGN KEY(tenant_id,participant_id) REFERENCES lesson_participants(tenant_id,id));
